"""Extract laser muzzle positions from the supplied ARM binary without executing it."""
from pathlib import Path
from inspect_original import Original


def main():
    original = Original()
    lines = [
        '// Generated by game/tools/import_laser_geometry.py; original ARM table 0x1f3078.',
        '#pragma once',
        '#include "engine/physics/collision/collider_shape.h"',
        '#include <algorithm>',
        '#include <array>',
        '#include <numbers>',
        'namespace game::play {',
        'inline constexpr std::array<elysia::core::Vector2,61> kLaserMuzzle{{',
    ]
    for frame in range(61):
        x, y = original.unpack('<2f', 0x1f3078 + frame * 8)
        lines.append(f'    {{{x:.6f}f,{y:.6f}f}},')
    lines.extend([
        '}};',
        '// Local Y-up orientation is quantized in three-degree steps, as in LaserBeam.',
        'inline elysia::core::Vector2 laser_muzzle_offset(float local_angle,elysia::core::Vector2 size) {',
        '    const int frame=std::clamp(static_cast<int>((180.-local_angle*180./std::numbers::pi)/3.),0,60);',
        '    const auto point=kLaserMuzzle[frame];',
        '    return {point.x-size.x/2,size.y/2-point.y};',
        '}',
        '// createShape (0xb6190): five vertices in metres relative to anchor (21,41.5).',
        'inline elysia::physics::ConvexPolygonShape laser_base_shape(elysia::core::Vector2 size) {',
        '    elysia::physics::ConvexPolygonShape shape;',
        '    shape.vertex_count=5;',
        '    constexpr std::array<elysia::core::Vector2,5> vertices{{{8,-28.8f},{0,-3.2f},{-8,-28.8f},{-8,-32},{8,-32}}};',
        '    for(int i=0;i<5;++i)shape.local_vertices[i]={21+vertices[i].x-size.x/2,size.y/2-41.5f-vertices[i].y};',
        '    return shape;',
        '}',
        '}',
    ])
    target = Path(__file__).resolve().parents[1] / 'gameplay/laser_geometry.h'
    target.write_text('\n'.join(lines) + '\n', encoding='utf8')
    print(target)


if __name__ == '__main__':
    main()
